#requires -Version 7.0
$ErrorActionPreference='Stop'
$repo=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'))
$game='C:\Program Files (x86)\Steam\steamapps\common\7 Days To Die'
$prod=Join-Path $game 'Mods/zzz_REBIRTH__3_0'
$relative='Scripts/Modules/BossEvents/RebirthBossNativePublication.cs'
$boss='Scripts/Modules/BossEvents/RebirthBossEvents.cs'
if((Get-FileHash (Join-Path $prod $relative)).Hash-ne'AFF031B431C24D2B9B85C19B3C5C8BA149CB05EDE9E66A079E9A6AB73ECBA6C8'-or(Get-FileHash (Join-Path $prod $boss)).Hash-ne'AFCA9FABB34FEB28740B5DC8D0040B0BDD3FEAAFA157C82C5E2A5E8E4D404B39'){throw 'Production integrated container baseline changed'}
function Extract($s,$marker){$a=$s.IndexOf($marker,[StringComparison]::Ordinal);if($a-lt0){throw $marker};$b=$s.IndexOf('{',$a);$arrow=$s.IndexOf('=>',$a);$semi=$s.IndexOf(';',$a);if($arrow-ge$a-and$arrow-lt$b-and$semi-lt$b){return $s.Substring($a,$semi-$a+1)};$n=0;$i=$b;do{if($s[$i]-eq'{'){$n++};if($s[$i]-eq'}'){$n--};$i++}while($n-gt0);$s.Substring($a,$i-$a)}
$s=[IO.File]::ReadAllText((Join-Path $repo $relative));$old=[IO.File]::ReadAllText((Join-Path $prod $relative));$events=[IO.File]::ReadAllText((Join-Path $prod $boss))
$begin=Extract $s 'internal static bool BeginRemoval('; $oldBegin=Extract $old 'internal static bool BeginRemoval('
if($old.Replace($oldBegin,$begin).Replace("`r`n","`n")-cne$s.Replace("`r`n","`n")){throw 'Unexpected runtime delta beyond BeginRemoval'}
$paths=@((Join-Path $prod $relative),(Join-Path $repo $relative),(Join-Path $prod $boss),(Join-Path $prod 'Scripts/Modules/BossEvents/RebirthBossPublicationCapture.cs'),(Join-Path $prod 'Scripts/Survivor/Persistence/RebirthStationSnapshotEvidence.cs'),(Join-Path $game '7DaysToDie_Data/Managed/Assembly-CSharp.dll'))
$guards=@($paths|ForEach-Object {[pscustomobject]@{path=$_;sha256=(Get-FileHash -LiteralPath $_).Hash}})
$methods=@();foreach($marker in @('internal static bool BeginRemoval(','internal static bool RemoveOriginal(','private static bool OriginalCurrent(','internal static bool Matches(','private static bool AliveIdentity(','internal static string Key(','internal static byte[] Stamp(','private static bool EnsureStamp(','internal static bool ValidProof(')){$methods+=Extract $s $marker;if($marker-ne'internal static bool BeginRemoval('-and(Extract $s $marker)-cne(Extract $old $marker)){throw ('Unchanged dependency drift '+$marker)}}
$methods+=$oldBegin.Replace('bool BeginRemoval(','bool BaselineBeginRemoval(')
$condition=[regex]::Match($old,'Func<bool> current=\(\)=>(ReferenceEquals\(GameManager.Instance\?\.World,world\)&&RebirthBossEventPersistence.IsReady&&original.RemovalInvoking[^;]+);').Groups[1].Value
if(!$condition){throw 'Actual absence admission condition unavailable'}
$probe='private sealed class Probe{internal RebirthBossEventInstance Event;internal Chunk Chunk;}internal static bool AbsenceAdmission(World world,RebirthBossEventInstance e,RebirthBossSpawnOriginal original){var item=new Probe{Event=e,Chunk=world.GetChunkSync(original.RemovalX,original.RemovalZ) as Chunk};return '+$condition+';}'
$models=Extract $events 'public sealed class RebirthBossSpawnOriginal'
$bound='private sealed class Bound{internal World World;internal RebirthBossEventInstance Event;internal RebirthBossSpawnOriginal Original;internal Entity Entity;}'
$doubles=@'
public struct Vector3{public float x,y,z;}public struct Vector3i{public int x,y,z;}
public class RebirthBossEventInstance{public Guid EventId=Guid.NewGuid();public Progression Progression=new Progression();public List<RebirthBossSpawnOriginal> SpawnOriginals=new List<RebirthBossSpawnOriginal>();}public class Progression{public string OwnerStableId="owner";}
public static class RebirthBossEventRegistry{public static RebirthBossEventInstance Current;public static bool TryGet(Guid id,out RebirthBossEventInstance e){e=Current;return e!=null&&e.EventId==id;}}
public static class RebirthBossEventPersistence{public static bool IsReady=true,Allow=true;public static int Calls;public static List<string> Order=new List<string>();public static bool Checkpoint(){Calls++;Order.Add("checkpoint");return Allow;}}
public static class ThreadManager{public static bool Main=true;public static bool IsMainThread()=>Main;}
public static class GameManager{public static Manager Instance=new Manager();public class Manager{public World World;}}
public class ChunkCustomData{public ChunkCustomData(){}public ChunkCustomData(string key,ulong expires,bool network){expiresInWorldTime=expires;isSavedToNetwork=network;}public byte[] data;public ulong expiresInWorldTime=ulong.MaxValue;public bool isSavedToNetwork;public object TriggerWriteDataDelegate;}
public class Chunk{public int X=5,Z=6;public bool isModified;public Custom ChunkCustomData=new Custom();public class Custom{public Dictionary<string,ChunkCustomData> dict=new Dictionary<string,ChunkCustomData>();public void Set(string key,ChunkCustomData value){dict[key]=value;RebirthBossEventPersistence.Order.Add("stamp");}}public bool InProgressUnloading;public List<Entity> entities=new List<Entity>();public void RemoveEntityFromChunk(Entity e){entities.Remove(e);}}
public enum EnumRemoveEntityReason{Despawned}
public class World{public State worldState=new State();public class State{public string Guid="world";}public bool remote;public Chunk chunk=new Chunk();public Dictionary<int,Entity> entities=new Dictionary<int,Entity>();public bool IsRemote()=>remote;public object GetChunkSync(int x,int z)=>chunk!=null&&chunk.X==x&&chunk.Z==z?chunk:null;public object GetChunkFromWorldPos(int x,int z)=>chunk;public Entity GetEntity(int id){entities.TryGetValue(id,out var e);return e;}public Entity RemoveEntity(int id,EnumRemoveEntityReason reason){var e=GetEntity(id);if(e==null)return null;e.MarkToUnload();entities.Remove(id);if(e.addedToChunk&&e.IsMarkedForUnload()&&!chunk.InProgressUnloading)chunk.RemoveEntityFromChunk(e);RebirthBossEventPersistence.Order.Add("native-remove");return e;}}
public class Entity{public World world;public int entityId=261,entityClass=764755902;public ulong WorldTimeBorn=33276;public bool addedToChunk=true,markedForUnload;public Vector3 position;public Vector3i chunkPosAddedEntityTo=new Vector3i{x=5,z=6};public virtual void MarkToUnload(){markedForUnload=true;}public virtual bool IsMarkedForUnload()=>markedForUnload;}
public class Buffs{Dictionary<string,float> vars=new Dictionary<string,float>();public float GetCustomVar(string k)=>vars.TryGetValue(k,out var v)?v:0;public void SetCustomVar(string k,float v){vars[k]=v;}}
public class EntityAlive:Entity{public Buffs Buffs=new Buffs();public int deathUpdateTime,timeStayAfterDeath=100;public override void MarkToUnload(){base.MarkToUnload();deathUpdateTime=timeStayAfterDeath;}public override bool IsMarkedForUnload()=>base.IsMarkedForUnload()&&deathUpdateTime>=timeStayAfterDeath;}
public class EntityClass{public static int FromString(string name)=>764755902;}public class EntityContainerAbs:Entity{}public class EntityBackpack:EntityContainerAbs{}public class ForeignLoot:EntityLootContainer{}public class EntityLootContainer:EntityContainerAbs{public bool bRemoved;public int calls;public void removeBackpack(string reason){calls++;RebirthBossEventPersistence.Order.Add("container-retire");bRemoved=true;MarkToUnload();}public override bool IsMarkedForUnload()=>base.IsMarkedForUnload()&&bRemoved;}
'@
$tests=@'
public static class Tests{static int count;static void Check(bool v,string label){if(!v)throw new Exception("FAIL "+label);count++;Console.WriteLine("PASS "+label);}
class Setup{public World w=new World();public RebirthBossEventInstance e=new RebirthBossEventInstance();public RebirthBossSpawnOriginal o;public Entity entity;public Setup(bool reward=false){ThreadManager.Main=true;RebirthBossEventPersistence.IsReady=true;RebirthBossEventPersistence.Allow=true;RebirthBossEventPersistence.Calls=0;RebirthBossEventPersistence.Order.Clear();GameManager.Instance.World=w;RebirthBossEventRegistry.Current=e;entity=reward?(Entity)new EntityLootContainer():new EntityAlive();entity.world=w;entity.position=new Vector3{x=80,z=96};o=new RebirthBossSpawnOriginal{Operation=Guid.NewGuid(),EntityId=entity.entityId,EntityClass=entity.entityClass,WorldTimeBorn=entity.WorldTimeBorn,Role=reward?3:0,Phase=3,Position=new Vector3{x=1,z=1},NativeProof=new string('a',64)};e.SpawnOriginals.Add(o);w.entities[entity.entityId]=entity;w.chunk.entities.Add(entity);if(entity is EntityAlive alive)RebirthBossNativePublication.SeedIdentity(alive,o);else Stamp();}public void Stamp(){w.chunk.ChunkCustomData.dict[RebirthBossNativePublication.Key(o)]=new ChunkCustomData{data=RebirthBossNativePublication.Stamp(w,e,o)};}}
static bool Remove(Setup s)=>RebirthBossNativePublication.RemoveOriginal(s.w,s.e,s.o,s.entity);
static void Refuse(Action<Setup> mutate,string label){var s=new Setup();mutate(s);Check(!Remove(s),label+" refused");Check(s.w.GetEntity(s.entity.entityId)!=null&&RebirthBossEventPersistence.Order.Count==0,label+" no stamp/checkpoint/native effect");}
public static void Run(){var b=new Setup();Check(RebirthBossNativePublication.Matches(b.w,b.e,b.o,b.entity),"actual early-CVar Matches admits moved original without destination stamp");Check(RebirthBossNativePublication.BaselineBeginRemoval(b.w,b.e,b.o,b.entity),"actual old BeginRemoval saves intent without destination stamp");b.w.RemoveEntity(b.entity.entityId,EnumRemoveEntityReason.Despawned);Check(!RebirthBossNativePublication.AbsenceAdmission(b.w,b.e,b.o),"actual old absence admission refuses absent moved original missing destination stamp");
var s=new Setup();Check(Remove(s),"current moved original removed after authored destination stamp");Check(s.o.RemovalX==5&&s.o.RemovalZ==6,"intent records exact current chunk after stamp");Check(RebirthBossNativePublication.AbsenceAdmission(s.w,s.e,s.o),"unchanged actual absence admission accepts stamped destination");Check(string.Join(",",RebirthBossEventPersistence.Order)=="stamp,checkpoint,native-remove","stamp precedes saved intent and native effect");Check(s.w.chunk.isModified,"native chunk marked modified for stamp save");Check(!s.o.NativeRemoved&&s.o.RemovalProof==""&&s.o.Phase==3&&s.o.NativeProof==new string('a',64),"admission does not invent removal/native/death proof");
s=new Setup();s.Stamp();var retained=s.w.chunk.ChunkCustomData.dict[RebirthBossNativePublication.Key(s.o)];Check(Remove(s)&&ReferenceEquals(retained,s.w.chunk.ChunkCustomData.dict[RebirthBossNativePublication.Key(s.o)]),"valid existing stamp retained without replacement");Check(string.Join(",",RebirthBossEventPersistence.Order)=="checkpoint,native-remove","existing valid stamp no duplicate write");
Refuse(x=>{x.Stamp();x.w.chunk.ChunkCustomData.dict[RebirthBossNativePublication.Key(x.o)].data[0]^=1;},"mismatched existing stamp");Refuse(x=>{x.Stamp();x.w.chunk.ChunkCustomData.dict[RebirthBossNativePublication.Key(x.o)].expiresInWorldTime=1;},"expired stamp metadata");Refuse(x=>{x.Stamp();x.w.chunk.ChunkCustomData.dict[RebirthBossNativePublication.Key(x.o)].isSavedToNetwork=true;},"network stamp metadata");Refuse(x=>{x.Stamp();x.w.chunk.ChunkCustomData.dict[RebirthBossNativePublication.Key(x.o)].TriggerWriteDataDelegate=new object();},"dynamic stamp metadata");
Refuse(x=>x.w.chunk=null,"chunk not loaded");Refuse(x=>x.w.chunk.InProgressUnloading=true,"chunk unloading");Refuse(x=>x.entity.entityClass++,"foreign class");Refuse(x=>x.entity.WorldTimeBorn++,"foreign birth");Refuse(x=>GameManager.Instance.World=new World(),"foreign current world");Refuse(x=>x.entity.world=new World(),"foreign entity world");Refuse(x=>x.w.entities[x.o.EntityId]=new EntityAlive{world=x.w},"foreign current object");Refuse(x=>x.e.SpawnOriginals.Clear(),"retired membership");Refuse(x=>x.o.NativeProof="","missing phase3 native proof");Refuse(x=>x.o.NativeProof=new string('z',64),"malformed native proof");Refuse(x=>x.o.Phase=2,"unpublished phase");Refuse(x=>x.entity.addedToChunk=false,"not native chunk member");Refuse(x=>ThreadManager.Main=false,"foreign thread");Refuse(x=>RebirthBossEventPersistence.IsReady=false,"unready persistence");Refuse(x=>x.w.remote=true,"remote world");Refuse(x=>x.o.Abandoned=true,"abandoned original");
s=new Setup();s.o.RemovalInvoking=true;s.o.RemovalX=3;s.o.RemovalZ=4;Check(!Remove(s)&&s.o.RemovalX==3&&s.o.RemovalZ==4&&RebirthBossEventPersistence.Order.Count==0,"existing intent coordinates never retargeted after movement");
s=new Setup();RebirthBossEventPersistence.Allow=false;Check(!Remove(s)&&s.w.GetEntity(s.o.EntityId)==s.entity&&s.w.chunk.entities.Contains(s.entity),"failed checkpoint retains native object");Check(string.Join(",",RebirthBossEventPersistence.Order)=="stamp,checkpoint"&&!s.o.NativeRemoved&&s.o.RemovalProof=="","failed checkpoint may retain stamp/intent but no effect or proof");RebirthBossEventPersistence.Allow=true;Check(Remove(s)&&string.Join(",",RebirthBossEventPersistence.Order)=="stamp,checkpoint,checkpoint,native-remove","same intent/chunk retries without duplicate stamp");
s=new Setup();s.w.entities.Clear();Check(!RebirthBossNativePublication.BeginRemoval(s.w,s.e,s.o,s.entity)&&s.w.chunk.ChunkCustomData.dict.Count==0,"already globally absent original never authorized for stamp recovery");
s=new Setup(true);Check(Remove(s)&&((EntityLootContainer)s.entity).bRemoved&&s.w.chunk.entities.Count==0,"integrated exact reward container retirement preserved");Check(string.Join(",",RebirthBossEventPersistence.Order)=="checkpoint,container-retire,native-remove","container effect ordering preserved");
Console.WriteLine("TOTAL "+count+" PASS; actual Boss methods/admission, native contract doubles; no gameplay/native acceptance");}}
'@
$source='using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;namespace BossStampControl{'+$models+$doubles+'internal static class RebirthBossNativePublication{'+$bound+($methods-join"`n")+$probe+'internal static void SeedIdentity(EntityAlive entity,RebirthBossSpawnOriginal original)=>AliveIdentity(entity,original,true);}'+$tests+'}'
Add-Type -TypeDefinition $source
$writer=[IO.StringWriter]::new();$prior=[Console]::Out
try{[Console]::SetOut($writer);[BossStampControl.Tests]::Run()}finally{[Console]::SetOut($prior)}
$writer.ToString()|Set-Content (Join-Path $repo '_Documentation/Purge/SUB7_BOSS_STAMP_CHECKS_20261029.txt')
$writer.ToString()
$domain=@'
