$api='using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using UnityEngine;namespace BossStampNativeApi{'+$models+$domain+'internal static class RebirthBossNativePublication{'+$bound+($methods-join"`n")+'}}'
$refs=@(Get-ChildItem (Join-Path $PSHOME 'ref') -Filter *.dll|ForEach-Object FullName)+@(Get-ChildItem (Join-Path $game '7DaysToDie_Data/Managed') -Filter *.dll|Where-Object {$_.Name-notmatch'^(System|Microsoft|mscorlib|netstandard)'}|ForEach-Object FullName)
Add-Type -TypeDefinition $api -ReferencedAssemblies $refs
$dotnetRoot=Split-Path (Get-Command dotnet).Source;$sdk=Get-ChildItem (Join-Path $dotnetRoot 'sdk') -Directory|Where-Object {$_.Name-like'9.*'}|Sort-Object Name|Select-Object -Last 1
Add-Type -Path (Join-Path $sdk.FullName 'Roslyn/bincore/Microsoft.CodeAnalysis.dll');Add-Type -Path (Join-Path $sdk.FullName 'Roslyn/bincore/Microsoft.CodeAnalysis.CSharp.dll')
if(@([Microsoft.CodeAnalysis.CSharp.CSharpSyntaxTree]::ParseText($s).GetDiagnostics()|Where-Object Severity -eq Error).Count){throw 'Whole source syntax error'}
